// ── BM25 KEYWORD SEARCH — Pinecone sparse vector query ──────────────────────
// Mirrors the ingestion BM25 chunker exactly: same hash function, same stopwords,
// same MAX_DIM. Must match or results will be wrong.
//
// SETUP: fill in PINECONE_HOST and PINECONE_API_KEY before running.
// ─────────────────────────────────────────────────────────────────────────────

const PINECONE_HOST = 'https://YOUR-INDEX-HOST.svc.YOUR-REGION.pinecone.io';
const PINECONE_API_KEY = 'YOUR-PINECONE-API-KEY';
const TOP_K = 5;
const MAX_DIM = 30000;

const STOPWORDS = new Set([
  'the','a','an','and','or','but','in','on','at','to','for','of',
  'with','by','from','is','are','was','were','be','been','have','has',
  'had','do','does','did','will','would','could','should','that','this',
  'it','as','not','if','they','we','you','he','she','i','its','about'
]);

function fnv1a(s) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h % MAX_DIM;
}

// Tokenise the query the same way as ingestion
const tokens = query.toLowerCase()
  .split(/[^a-z0-9]+/)
  .filter(t => t.length > 2 && !STOPWORDS.has(t));

if (tokens.length === 0) return 'Query too short or contains only stopwords.';

const tf = {};
for (const t of tokens) tf[t] = (tf[t] || 0) + 1;
const maxFreq = Math.max(1, ...Object.values(tf));

const seen = new Set();
const indices = [], values = [];
for (const [tok, freq] of Object.entries(tf)) {
  const idx = fnv1a(tok);
  if (!seen.has(idx)) {
    seen.add(idx);
    indices.push(idx);
    values.push(parseFloat((freq / maxFreq).toFixed(4)));
  }
}

// Query Pinecone with sparse vector only (keyword retrieval)
const res = await fetch(`${PINECONE_HOST}/query`, {
  method: 'POST',
  headers: {
    'Api-Key': PINECONE_API_KEY,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    sparseVector: { indices, values },
    filter: { strategy: { '$eq': 'keyword' } },
    topK: TOP_K,
    includeMetadata: true
  })
});

if (!res.ok) return `Pinecone error: ${res.status} ${await res.text()}`;

const data = await res.json();
const matches = data.matches || [];
if (matches.length === 0) return 'No keyword matches found.';

return matches
  .map((m, i) => `[${i + 1}] Source: ${m.metadata?.label || 'Unknown'}\n${m.metadata?.text || ''}`)
  .join('\n\n---\n\n');
